# Sourced by the scripts that restore local tools in solutions generated by generate-app.sh, whose packages live in a private folder.
# isolate_dotnet_cli_home <dir> keeps the resolver cache of local tools in <dir>/dotnet-cli for the rest of the calling script.
# The SDK never rewrites an entry of that cache for a tool version it already knows: in the shared cache, an entry for
# hardslice.tool or dotnet-ef would keep pointing to the private folder once it is deleted, or to a folder the caller does not trust.
# NuGet takes its home from DOTNET_CLI_HOME as well: its download cache stays where it was.
isolate_dotnet_cli_home() {
  local repo_root
  repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
  if [[ -z "${NUGET_HTTP_CACHE_PATH:-}" ]]; then
    NUGET_HTTP_CACHE_PATH="$(cd "$repo_root" && dotnet nuget locals http-cache --list | sed -n 's/^http-cache: //p')"
    export NUGET_HTTP_CACHE_PATH
  fi
  export DOTNET_CLI_HOME="$1/dotnet-cli"
}
